@pytest.fixture(scope="session")
def exact_query() -> tuple[bytes, list[int]]:
    positive = frozenset(
        int(token)
        for token in gzip.decompress(base64.b64decode(_POSITIVE_GZIP_BASE64))
        .decode("ascii")
        .split(",")
    )
    instance = _new_instance(2)
    cnf = instance.dimacs().encode("utf-8")
    assignment = [
        variable if variable in positive else -variable
        for variable in range(1, instance.cnf.n_variables + 1)
    ]
    return cnf, assignment


class FakePiqd:
    def __init__(
        self,
        *,
        cnf: bytes,
        result: str,
        assignment: list[object] | None = None,
    ) -> None:
        self.cnf = cnf
        self.result = result
        self.assignment = assignment
        self.producer = b""
        self.job_id = "five-omission-job-001"
        self.status_job_id = self.job_id
        self.calls: list[tuple[str, str]] = []
        self.fail_at: tuple[str, str] | None = None
        self.hook: Callable[[str, str], None] | None = None

    @staticmethod
    def _json(value: dict[str, Any]) -> HttpResponse:
        return HttpResponse(
            200,
            canonical_json_bytes(value),
            {"Content-Type": "application/json"},
        )

    def __call__(
        self,
        method: str,
        url: str,
        body: bytes | MultipartBody | None,
        _headers: object,
    ) -> HttpResponse:
        parsed = urllib.parse.urlsplit(url)
        path = parsed.path + (f"?{parsed.query}" if parsed.query else "")
        self.calls.append((method, path))
        if self.hook is not None:
            self.hook(method, path)
        if self.fail_at == (method, path):
            raise OSError("injected fake-transport failure")
        cnf_sha256 = sha256_bytes(self.cnf)
        producer_sha256 = sha256_bytes(self.producer)
        identity = raw_dimacs_identity(
            backend="cadical",
            solver_profile="sat",
            cnf_sha256=cnf_sha256,
            producer_manifest_sha256=producer_sha256,
            requested_core_limit=1,
        )
        if method == "POST" and path == "/jobs/prepare-cnf":
            assert isinstance(body, bytes)
            assert self.cnf in body
            assert self.producer in body
            num_variables, num_clauses = scan_dimacs(self.cnf)
            return self._json(
                {
                    "job_id": self.job_id,
                    "cnf_blob_hash": cnf_sha256,
                    "identity_hash": identity,
                    "num_vars": num_variables,
                    "num_clauses": num_clauses,
                    "preview": "",
                    "existing": False,
                    "requested_core_limit": 1,
                }
            )
        if method == "GET" and path == f"/jobs/{self.job_id}/cnf":
            return HttpResponse(
                200,
                self.cnf,
                {"Content-Type": "application/octet-stream"},
            )
        if method == "POST" and path == f"/jobs/confirm?job_id={self.job_id}":
            return self._json({"job_id": self.job_id, "status": "confirmed"})
        if method == "GET" and path == f"/jobs/{self.job_id}":
            return self._json(
                {
                    "id": self.status_job_id,
                    "status": "completed",
                    "result": self.result,
                    "requested_core_limit": 1,
                    "progress": {"solver_started": True},
                    "attested_solver_processes": 1,
                    "attestation_basis": "SINGLE_PROCESS_NO_PARALLEL_FLAG",
                }
            )
        if method == "GET" and path == f"/jobs/{self.job_id}/model":
            assignment = self.assignment if self.assignment is not None else []
            return self._json(
                {
                    "job_id": self.job_id,
                    "result": "SAT",
                    "num_assigned": len(assignment),
                    "assignment": assignment,
                }
            )
        if method == "GET" and path.startswith(f"/jobs/{self.job_id}/log?"):
            payload = f"s {self.result}\n".encode()
            return HttpResponse(
                200,
                payload,
                {
                    "Content-Type": "text/plain; charset=utf-8",
                    "X-Log-Size-Bytes": str(len(payload)),
                },
            )
        if method == "GET" and path == f"/jobs/{self.job_id}/proof":
            raise AssertionError("PIQD observational UNSAT must not fetch a proof")
        raise AssertionError((method, path))


def _discovery(
    tmp_path: Path,
    api: FakePiqd,
    *,
    repo_root: Path = REPO_ROOT,
    seed_journal: Path | None = None,
    shared_bank: Path | None = None,
):
    discovery = make_five_omission_piqd_discovery(
        repo_root=repo_root,
        base_url="http://piqd.invalid",
        journal_root=tmp_path / "piqd",
        deleted_label=2,
        seed_journal=seed_journal,
        shared_bank=shared_bank,
        transport=api,
        sleep=lambda _seconds: None,
    )
    api.producer = discovery.bundle.producer_manifest_bytes
    return discovery


def _run_with_discovery(
    tmp_path: Path,
    discovery: object,
    *,
    local_terminal: Callable[..., CadicalResult] | None = None,
) -> dict[str, Any]:
    workdir = tmp_path / "run"
    with (
        patch.object(
            adapter, "make_five_omission_piqd_discovery", return_value=discovery
        ),
        patch.object(
            cegar,
            "_solve_persisted_cadical",
            side_effect=local_terminal
            if local_terminal is not None
            else AssertionError("local discovery/terminal fallback is forbidden"),
        ),
    ):
        return run_five_omission_piqd(
            REPO_ROOT,
            workdir,
            2,
            piqd_base_url="http://piqd.invalid",
            piqd_journal_root=tmp_path / "piqd",
            max_iterations=1,
            timeout_seconds=5,
        )


def test_piqd_sat_is_total_replayed_and_learns_one_cut(
    tmp_path: Path, exact_query: tuple[bytes, list[int]]
) -> None:
    cnf, assignment = exact_query
    api = FakePiqd(cnf=cnf, result="SAT", assignment=assignment)
    discovery = _discovery(tmp_path, api)
    proof_arguments: list[Path | None] = []
    shared_runner = discovery.runner

    def recording_runner(
        cnf_path: Path, timeout_seconds: int, proof_path: Path | None
    ) -> StaticSolverResult:
        proof_arguments.append(proof_path)
        return shared_runner(cnf_path, timeout_seconds, proof_path)

    discovery.runner = recording_runner
    result = _run_with_discovery(tmp_path, discovery)
    summary = result["legacy_summary"]
    assert summary["status"] == "ITERATION_LIMIT"
    assert summary["records"] == 1
    assert summary["discovery_verdict"] == "SAT"
    assert proof_arguments == [None]
    assert len((tmp_path / "run" / "journal.jsonl").read_text().splitlines()) == 1
    assert Path(result["piqd_result_path"]).read_bytes() == (
        canonical_json_bytes(result["piqd_result"]) + b"\n"
    )
    assert result["piqd_result"]["piqd_proof_obtained"] is False
    assert all(value is False for value in result["piqd_result"]["claims"].values())
    assert not any(path.endswith("/proof") for _method, path in api.calls)


def test_piqd_unsat_triggers_exactly_one_local_terminal_rerun(
    tmp_path: Path, exact_query: tuple[bytes, list[int]]
) -> None:
    cnf, _assignment = exact_query
    api = FakePiqd(cnf=cnf, result="UNSAT")
    discovery = _discovery(tmp_path, api)
    calls: list[tuple[Path, Path | None]] = []

    def local_terminal(
        _instance: object,
        cnf_path: Path,
        _expected_hash: str,
        *,
        timeout_seconds: int,
        nice: int,
        tool_manifest: object,
        proof_path: Path | None = None,
    ) -> CadicalResult:
        assert timeout_seconds == 5
        assert nice == 10
        assert tool_manifest
        calls.append((cnf_path, proof_path))
        assert proof_path == tmp_path / "run" / "terminal.drat"
        cegar._write_regular_bytes(proof_path, b"fake terminal drat", create=True)
        return CadicalResult("UNSAT", None, 20, True, "fake terminal verified")

    result = _run_with_discovery(
        tmp_path,
        discovery,
        local_terminal=local_terminal,
    )
    summary = result["legacy_summary"]
    assert summary["status"] == "UNSAT_DRAT_VERIFIED"
    assert summary["discovery_verdict"] == "UNSAT"
    assert summary["terminal_proof_verified"] is True
    assert calls == [
        (
            tmp_path / "run" / "terminal.cnf",
            tmp_path / "run" / "terminal.drat",
        )
    ]
    assert (tmp_path / "run" / "discovery.cnf").read_bytes() == (
        tmp_path / "run" / "terminal.cnf"
    ).read_bytes()
    assert not any(path.endswith("/proof") for _method, path in api.calls)
    assert result["piqd_result"]["piqd_proof_obtained"] is False


@pytest.mark.parametrize("mode", ["UNKNOWN", "transport-error"])
def test_unknown_and_transport_error_never_fall_back_locally(
    tmp_path: Path,
    exact_query: tuple[bytes, list[int]],
    mode: str,
) -> None:
    cnf, _assignment = exact_query
    api = FakePiqd(cnf=cnf, result="UNKNOWN")
    if mode == "transport-error":
        api.fail_at = ("GET", f"/jobs/{api.job_id}")
    discovery = _discovery(tmp_path, api)
    result = _run_with_discovery(tmp_path, discovery)
    assert result["legacy_summary"]["status"] == "UNKNOWN"
    assert result["legacy_summary"]["terminal_verdict"] is None
    assert not (tmp_path / "run" / "terminal.cnf").exists()
    assert not (tmp_path / "run" / "terminal.drat").exists()


