@pytest.mark.parametrize("input_name", ["seed_journal", "shared_bank"])
def test_seed_and_shared_bank_identity_tampering_fails_before_transport(
    tmp_path: Path,
    exact_query: tuple[bytes, list[int]],
    input_name: str,
) -> None:
    cnf, _assignment = exact_query
    source = tmp_path / f"{input_name}.json"
    source.write_bytes(b"" if input_name == "seed_journal" else b"{}\n")
    api = FakePiqd(cnf=cnf, result="UNKNOWN")
    kwargs = {input_name: source}
    discovery = _discovery(tmp_path, api, **kwargs)
    replacement = tmp_path / f"{input_name}.replacement"
    replacement.write_bytes(source.read_bytes())
    os.replace(replacement, source)
    query = tmp_path / "query.cnf"
    query.write_bytes(cnf)
    with pytest.raises(FiveOmissionPiqdError, match="bound source or input changed"):
        discovery(query, 5, None)
    assert api.calls == []


def _mirror_sources(root: Path) -> None:
    for relative in (*FORMULA_FILES, *DETECTOR_FILES, *_EXTRA_SOURCE_FILES):
        destination = root / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(REPO_ROOT / relative, destination)


def test_source_identity_and_bundle_manifest_tampering_fail_closed(
    tmp_path: Path,
    exact_query: tuple[bytes, list[int]],
) -> None:
    cnf, _assignment = exact_query
    mirror = tmp_path / "mirror"
    _mirror_sources(mirror)
    api = FakePiqd(cnf=cnf, result="UNKNOWN")
    discovery = _discovery(tmp_path, api, repo_root=mirror)
    target = mirror / FORMULA_FILES[0]
    replacement = target.with_suffix(".replacement")
    replacement.write_bytes(target.read_bytes())
    os.replace(replacement, target)
    query = tmp_path / "query.cnf"
    query.write_bytes(cnf)
    with pytest.raises(FiveOmissionPiqdError, match="bound source or input changed"):
        discovery(query, 5, None)
    assert api.calls == []

    # A separate create-once bundle detects installed manifest mutation too.
    other = _discovery(tmp_path / "other", FakePiqd(cnf=cnf, result="UNKNOWN"))
    manifest = other.bundle.directory / "source-manifest.json"
    manifest.write_bytes(manifest.read_bytes() + b" ")
    other_query = tmp_path / "other-query.cnf"
    other_query.write_bytes(cnf)
    with pytest.raises(FiveOmissionPiqdError, match="custody|byte bound"):
        other(other_query, 5, None)


