def test_builtin_scalar_and_exact_result_shapes_are_enforced(tmp_path: Path) -> None:
    class IntSubclass(int):
        pass

    class StrSubclass(str):
        pass

    for malformed in (True, 2.0, IntSubclass(2)):
        with pytest.raises(FiveOmissionPiqdError, match="builtin Fin 12"):
            _build_bundle(
                repo_root=REPO_ROOT,
                custody_root=tmp_path / "unused",
                deleted_label=malformed,  # type: ignore[arg-type]
                seed_journal=None,
                shared_bank=None,
            )

    valid = {variable: False for variable in range(1, 4)}
    malformed_results = (
        StaticSolverResult("SAT", {True: False, 2: False, 3: False}, 10),
        StaticSolverResult("SAT", {1: 0.0, 2: False, 3: False}, 10),
        StaticSolverResult("SAT", valid, True),
        StaticSolverResult("SAT", valid, 10.0),  # type: ignore[arg-type]
        StaticSolverResult("SAT", valid, IntSubclass(10)),
        StaticSolverResult(StrSubclass("SAT"), valid, 10),
        StaticSolverResult("UNSAT", {1: False}, 20),
    )
    for malformed in malformed_results:
        with pytest.raises(FiveOmissionPiqdError):
            _validate_static_result(malformed, num_variables=3)

    class DictSubclass(dict[int, bool]):
        pass

    with pytest.raises(FiveOmissionPiqdError, match="container"):
        _validate_static_result(
            StaticSolverResult("SAT", DictSubclass(valid), 10),
            num_variables=3,
        )


