@pytest.mark.parametrize("tamper", ["mutate", "replace"])
def test_summary_race_before_sidecar_install_fails_without_publication(
    tmp_path: Path,
    exact_query: tuple[bytes, list[int]],
    tamper: str,
) -> None:
    cnf, _assignment = exact_query
    api = FakePiqd(cnf=cnf, result="UNKNOWN")
    discovery = _discovery(tmp_path, api)
    original_verify = adapter._verify_bundle
    raced = False

    def verify_then_race(bundle: object) -> None:
        nonlocal raced
        original_verify(bundle)  # type: ignore[arg-type]
        summary_path = tmp_path / "run" / "summary.json"
        if raced or not summary_path.exists():
            return
        raced = True
        if tamper == "mutate":
            summary_path.write_bytes(summary_path.read_bytes() + b" ")
        else:
            replacement = summary_path.with_suffix(".replacement")
            replacement.write_bytes(summary_path.read_bytes())
            os.replace(replacement, summary_path)

    with (
        patch.object(adapter, "_verify_bundle", side_effect=verify_then_race),
        pytest.raises(FiveOmissionPiqdError, match="summary.json.*changed"),
    ):
        _run_with_discovery(tmp_path, discovery)
    assert raced is True
    assert not (tmp_path / "run" / adapter.RESULT_FILENAME).exists()


def test_publication_rechecks_original_sources_after_legacy_completion(
    tmp_path: Path,
    exact_query: tuple[bytes, list[int]],
) -> None:
    cnf, _assignment = exact_query
    mirror = tmp_path / "mirror"
    _mirror_sources(mirror)
    api = FakePiqd(cnf=cnf, result="UNKNOWN")
    discovery = _discovery(tmp_path, api, repo_root=mirror)
    actual_legacy_run = adapter.run_five_omission_cegar
    target = mirror / "census/p97_search/phase3_cegar_wave.py"

    def run_then_tamper(*args: object, **kwargs: object) -> dict[str, Any]:
        summary = actual_legacy_run(*args, **kwargs)  # type: ignore[arg-type]
        target.write_bytes(target.read_bytes() + b"\n")
        return summary

    workdir = tmp_path / "run"
    with (
        patch.object(
            adapter, "make_five_omission_piqd_discovery", return_value=discovery
        ),
        patch.object(adapter, "run_five_omission_cegar", side_effect=run_then_tamper),
        patch.object(
            cegar,
            "_solve_persisted_cadical",
            side_effect=AssertionError("local fallback is forbidden"),
        ),
        pytest.raises(FiveOmissionPiqdError, match="bound source or input changed"),
    ):
        run_five_omission_piqd(
            mirror,
            workdir,
            2,
            piqd_base_url="http://piqd.invalid",
            piqd_journal_root=tmp_path / "piqd",
            max_iterations=1,
            timeout_seconds=5,
        )
    assert not (workdir / adapter.RESULT_FILENAME).exists()


def test_cli_malformed_shared_bank_is_structured_pipeline_error(
    tmp_path: Path,
    capsys: pytest.CaptureFixture[str],
) -> None:
    shared_bank = tmp_path / "malformed-shared-bank.json"
    shared_bank.write_bytes(b"{}\n")
    argv = [
        "source_faithful_five_omission_piqd.py",
        "--repo-root",
        str(REPO_ROOT),
        "--workdir",
        str(tmp_path / "run"),
        "--deleted-label",
        "2",
        "--piqd-base-url",
        "http://piqd.invalid",
        "--piqd-journal-root",
        str(tmp_path / "piqd"),
        "--shared-bank",
        str(shared_bank),
        "--max-iterations",
        "1",
    ]

    def forbidden_runner(*_args: object, **_kwargs: object) -> None:
        raise AssertionError("malformed bank must fail before discovery transport")

    with (
        patch.object(sys, "argv", argv),
        patch.object(
            adapter,
            "make_static_piqd_solver_runner",
            return_value=forbidden_runner,
        ),
    ):
        assert adapter.main() == 2
    output = json.loads(capsys.readouterr().out)
    assert output["status"] == "PIPELINE_ERROR"
    assert "shared bank" in output["error"]


@pytest.mark.parametrize("unexpected", [RuntimeError("boom"), KeyboardInterrupt()])
def test_cli_does_not_catch_unexpected_or_base_exceptions(
    tmp_path: Path,
    unexpected: BaseException,
) -> None:
    argv = [
        "source_faithful_five_omission_piqd.py",
        "--workdir",
        str(tmp_path / "run"),
        "--deleted-label",
        "2",
        "--piqd-base-url",
        "http://piqd.invalid",
        "--piqd-journal-root",
        str(tmp_path / "piqd"),
    ]
    with (
        patch.object(sys, "argv", argv),
        patch.object(adapter, "run_five_omission_piqd", side_effect=unexpected),
        pytest.raises(type(unexpected)),
    ):
        adapter.main()
